import{_ as l,a,b as r,c as i,d as o}from"./chunks/cd9dd908f875497aaf28.BEAhqp0s.js";import{_ as s,C as n,o as h,c as m,j as e,a as c,E as d,a6 as u}from"./chunks/framework.CnPv4DE1.js";const T=JSON.parse('{"title":"聪明人最好的一人企业(2025)","description":"","frontmatter":{"title":"聪明人最好的一人企业(2025)","originalTitle":"The Best One-Person Business For Smart People (2025)","date":"2024-10-19","originalUrl":"https://thedankoe.com/letters/the-best-one-person-business-for-smart-people-2025/","minutes":18,"sourceHash":"b41b3a1a8787a132088364c6075db4daf59c3fb83e6034aeebf74e844cee4ed7","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-best-one-person-business-for-smart-people-2025/"}]]},"headers":[],"relativePath":"letters/the-best-one-person-business-for-smart-people-2025.md","filePath":"letters/the-best-one-person-business-for-smart-people-2025.md"}'),_={name:"letters/the-best-one-person-business-for-smart-people-2025.md"};function b(f,p,g,k,P,q){const t=n("ArticleMeta");return h(),m("div",null,[p[0]||(p[0]=e("h1",{id:"聪明人最好的一人企业-2025",tabindex:"-1"},[c("聪明人最好的一人企业(2025) "),e("a",{class:"header-anchor",href:"#聪明人最好的一人企业-2025","aria-label":'Permalink to "聪明人最好的一人企业(2025)"'},"​")],-1)),d(t),p[1]||(p[1]=u('<p><a href="https://www.youtube.com/embed/cNGpxfcDKms?si=vPwXA9-Vb_NX5SJz" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我想让你和我一起想象一下未来。</p><p>一个这样的世界：</p><ul><li>创作者是新一代的老师。</li><li>在线课程是去中心化的教育。</li><li>个人追求自己的兴趣，教导与自己性格相似的人，从而创造出更好的学习体验。</li><li>教育比循规蹈矩的公立学校系统更高效、更实惠、更注重结果。</li><li>任何人都可以选择符合自己个人目标的课程和创作者。他们不会被锁死在一个会滋生狭隘思维、依赖社会才能获得工作或薪水的单一研究领域里。</li><li>越来越多的人拥抱深度通才主义，成为博学多才的人，这是成为一个自由思考的个体的先决条件。</li><li>学习、教学和赚钱融合成一种理想而有意义的生活方式（这要归功于科技的进步和信息的传播）。</li></ul><p>你现在正在经历这一切。</p><p>你现在正在阅读一封信，其中的信息可能会改变你的人生（而学校绝不敢教授这些内容，因为这会把你从他们的体系中解放出来，而他们不会从中获益）。</p><p>在我看来，这就是教育、创业以及整个工作方式的未来。</p><p>所有的迹象都指向这一点。</p><p>在这封信中，我想向你展示一条任何人都可以走的道路，来保障自己的未来。</p><p>这不是一条每个人都做同样事情的道路。</p><p>这是一条人们可以追求自己的兴趣、倾向于讲述让自己独一无二的故事的道路。一条在合理范围内，每个人都能因为做自己而获得报酬的道路——在这个世界里，机械化的工作正在被大规模自动化取代。</p><p>如果你观看那段视频，我会处理你对这是否是大多数人可行道路的大部分疑问。</p><p>当然，这只是一个预测，但数据是压倒性的，而且只要投入足够的关注和努力去创造那个现实，预测是可以成真的。</p><p>让我们来看一下：</p><p>首先，来自Stripe（一家支付公司）的数据显示，创作者的增长短期内不会停止。</p><p>（这些图片来自<a href="https://x.com/hosun_chung/status/1845491689793982641" target="_blank" rel="noreferrer">Hosun的X帖子</a>，讨论的是类似话题。这是我自己的看法，过去我们已经讨论过很多次，但这次的观点比以往更加精炼。）</p><p><img src="'+l+'" alt=""></p><p>在我看来，随着AI和自动化让毫无意义的工作变得可选，创作者的增长是唯一合乎逻辑的选择。</p><p>尽管社交媒体可能会变化，但追求自己兴趣、并因做自己而获得报酬的渴望始终存在。而且，如果你没注意到的话，进化的本质就是解决问题。为了引导进化走到这一步，已经耗费了大量的科技投入，但我们正处于解决“做自己厌恶的工作”这一问题的边缘。当然，原则依旧不变：这一切都不会白白送给你。</p><p>这种生活是为博学多才者、自学者，以及那些对获取多样化、不可替代技能有着永不满足渴望的人所保留的。</p><p>让我们继续深入。</p><p><img src="'+a+'" alt=""></p><p>SignalFire的一张图表显示，目前已有5000万内容创作者。除此之外：</p><ul><li>自由职业者占劳动力的46.6%（相比2020年的36%大幅增长）。</li><li>创作者经济预计将从2500亿美元翻倍增长到2028年的4800亿美元。人们以为自己错过了这场盛宴，其实它才刚刚开始。</li><li>经济更青睐盈利能力强的商业模式。像创作者这样借助科技的企业，凭借数字产品和服务可以实现95%的利润率——这促使该领域在新平台和工具上出现更多发展。</li><li>大公司要求企业领导者在社交媒体上保持活跃，以维护品牌声誉。企业化营销减少，人性化营销增多。</li></ul><p>企业开始倾向于选择承包商和创作者，作为员工和营销人员。</p><p>简而言之，未来更青睐那些个人、小团队，以及那些不再试图把人锁死在他们厌恶的生活中的进取型公司。既然人们已经拥有了实现自主的技术，他们将全力反抗。</p><p>还有另外一件事……</p><p>科技已经进化了。</p><p>现在你不需要10个开发人员的团队来建一个网站。</p><p>你有无代码的拖拽式工具，可以帮你快速搭建。</p><p>你不需要花钱买广告牌或电台广告时段。你只需发布内容，吸引人们关注你的创意作品和业务。</p><p>大多数人认为AI会取代创意工作者。</p><p>如果真的如此，也许你本就该被取代，你并没有自己以为的那么有创造力。</p><p>AI只是让聪明人能够以个人或团队的身份做得更多。人们在一个周末内就能构建出爆火的应用程序，写内容的速度也比以往更快。这些应用和内容的质量，取决于一整套广泛的技能，而这些是仅靠向ChatGPT打字无法弥补的。</p><p>这对通才和博学者来说是一种超能力。</p><p>但这背后的道理还要更深。</p><h2 id="聪明人不该上大学" tabindex="-1">聪明人不该上大学 <a class="header-anchor" href="#聪明人不该上大学" aria-label="Permalink to &quot;聪明人不该上大学&quot;">​</a></h2><blockquote><p>学校里找不到的知识，正是职场中找不到的财富的源泉。——《专注的艺术》</p></blockquote><p>人们正在对那些没能给他们带来所承诺的稳定未来的机构和思想体系失去信任。</p><p><img src="'+r+'" alt=""></p><p>学校让你的思维局限在一份体面工作和一份丰厚薪水这种虚幻的社会地位上。</p><p>宗教让你的思维局限在一种单一的文化视角上，而这种视角无法解释现实。</p><p>工作让你的思维局限在一系列可替代、重复性的任务上，随着科技的进步，这些任务将不再值现在支付给你的薪水。</p><p>对于那些重视自我教育和个人责任的人来说，你很可能正在经历人生中最重要的时刻。</p><p>对于那些无法独立思考、无法向新视角敞开心胸的人来说，未来几年你可能会持续受苦，直到触底——那种境遇会强迫你转变视角、获得成长。</p><p>在自我发展理论（Ego Development Theory）中，一个较低的发展阶段是“循规蹈矩”阶段。在这个阶段，人们无法独立思考。他们需要被部落所接纳。因此他们的思维把宗教及其他意识形态和体制教条当作法律。不仅对圣经如此，对其他一切也是“圣经狂热者”式的盲信。</p><p>看起来，随着新一代人逐渐获得更多的集体话语权，那个主要由“婴儿潮一代”占据的循规蹈矩阶段，正慢慢从大众中淡出。越来越多的人正处于更高的发展阶段。</p><p>这就是社交媒体和互联网隐藏的重要性所在。</p><p>社交媒体为教育、意义和工作的分发奠定了基础。</p><p>界限已经模糊。在任何一种文化中，没有一个中央机构能够独自掌控其中任何一项。</p><p>社交媒体上的个人品牌传授自己的兴趣，分享自己的信念体系，并通过在自己品牌下提供产品或服务来赚取收入。</p><p>为什么这是历史上如此重要的一个转折点？</p><ol><li>任何人都可以自由地在互联网上分享自己的兴趣和信念。</li><li>任何人都可以自由地自我发展，获取新技能，向他人学习，并通过提供自己的产品或服务为人类做出贡献。</li><li>教育决定了一个人的潜力，而如果这种教育被一个不顾及个人目标和发展、有自身议程的学校系统所主导，那么我们正在进入一个新的黄金时代。</li></ol><p>教育塑造未来，因为它塑造人类行为。你会变成你所吸收的东西。</p><p>教育拓展你的视野，让你能在未知的领域中发现机会。</p><p>教育就是编程。你一生都在被教育。但直到现在，你才第一次能够自己选择那教育的来源。</p><p>换句话说，我们正在进入一种人本经济。</p><p>一种真正反映自然规律的互联经济。</p><p>一种目的驱动的经济，人们可以选择向那些与自己有共同愿景和目标的人学习。</p><p>为什么这行得通？</p><p>因为人们对理解的需求各不相同。</p><p>你们中的许多人来到这里，是因为你们对我所说、所教的内容有共鸣。</p><p>另一些人厌恶我，但他们从另一个角度获得了类似的信息，这也没关系。这只是性格和教学风格上的差异。</p><p>传统学生被分配了目标，这让他们变得愚钝且可被替代。他们被分配了老师。他们被告知要支付一笔离谱的费用。要借出根本不可能还清的贷款。让他们淹没在高额利息中，这种压力使他们的思维一直被困在生存模式里。他们试图通过找一份工作来缓解这种压力，结果却让生活变得更糟。等他们意识到时，他们或者忘记了自己本该拥有更好的命运，或者被摆脱这个烂摊子所需的巨大工作量给压垮了。</p><p>现代学生可以选择自己的目标，找到一位老师，投资于自己的教育，一旦实现了那个目标，他们就可以像万物一样进化到下一个阶段，或者他们可以满足自己更高层次的需求——成为老师，将所学传授下去。</p><p>如果你不能成为一个有价值的人，你要怎么创造出值得传播的东西？</p><p>是的，要加入这个新的、超高盈利能力的经济体，你需要在自己的人生中做出些什么。</p><p>但传统教育是不够的。</p><p>目前的学校系统本质上就是一个体系。</p><p>一个把你塑造成劳动力的体系。</p><p>它教授的是在旧经济中打一份工所需的服从性和技能。</p><p>如果你想在新经济中赚钱，那么显然你必须向那些在这个领域取得成果的人学习。</p><p>来自那些<em>创造出</em>这些赚钱方式的品牌和创作者的课程、指导和内容。</p><p>尽管许多人认为这些是骗局——确实有一些是骗局，因为这个领域还很新，尚未经过进化式的自我纠正——但你能做的最糟糕的事，就是避免向那些正在你眼前创造未来的人学习。</p><p>新的工作岗位正在大量涌现。</p><p>那些婴儿潮一代会告诉你去“找份正经工作”的岗位。</p><p>创作者们正在开辟一条新道路，创造价值，组建团队，招募高能动性的人才。</p><p>创作者经济就是新的学校系统。成为创作者就是新的职业道路。一条能让你追求并将任何你认为有意义、重要的兴趣变现的整体性职业道路。</p><p>设定一个目标。</p><p>找到与你产生共鸣的创作者。</p><p>沉浸在他们提供的信息之中。</p><p>观察新的机会在你的意识中逐渐显现。</p><p>像你的生命依赖于此一样去行动。</p><h2 id="一人媒体公司——你的学校系统" tabindex="-1">一人媒体公司——你的学校系统 <a class="header-anchor" href="#一人媒体公司——你的学校系统" aria-label="Permalink to &quot;一人媒体公司——你的学校系统&quot;">​</a></h2><p>如果你理解进化，你就会明白，个人、行业乃至生命本身都在统一与分裂之间摇摆。</p><p>集中化与去中心化。</p><p>这是现实世界的一个普遍原则。</p><p>就像海洋蒸发成水滴，在云中凝结，一旦重到一定程度，便化作雨水落下，滋养植物，服务于其他有益的生态功能，然后周而复始。</p><p>我们正在进入一个钟摆从机构摆向个人的时代。</p><p>熵与财富是两个极端。</p><p>随着不确定性或混乱程度的增加,你拥有的用以创造财富的机会和资源也就越多。财富就是通过价值创造来增加秩序。就像把木材变成房子(把低价值变成高价值)。</p><p>这一切哲学上的说辞,其实是想说,我们生活在一个人们对制度掌控我们心智深感不确定和不信任的时代。但这并不是坏事。它只是意味着,作为<strong>个体</strong>,我们拥有更多信息、更多想法、更多资源——比如其他价值创造者孕育出的无代码工具——以及更多可以利用的丰盛。</p><p>让我们来拆解一下这是如何运作的:</p><h3 id="_1-创业的未来" tabindex="-1">1) 创业的未来 <a class="header-anchor" href="#_1-创业的未来" aria-label="Permalink to &quot;1) 创业的未来&quot;">​</a></h3><p>社交媒体是眼下注意力所在的地方。</p><p>社交媒体是一项免费的技术,它彻底改变了我们学习和获取知识、提升生活质量的方式(这是对那些注重价值的人而言……那些低发展水平、专注于表情包和恶意言论的人,不应该是你关注的对象)。</p><p>社交媒体是你加入未来工作方式的途径。</p><p>是的,我相信,从足够长的时间尺度来看,我们用来创造财富的方式将会从实体转向数字。</p><p>实体企业都拥有在线商店和受众,以此来扩大影响力、提供更多价值。</p><p>各大公司正在培养“内部创作者”,为其机械化的企业注入更多个性。</p><p>像 Ali Abdaal(阿里·阿布达尔)——我们的生产力霸主——这样的个体,辞去了医生的工作。他发布了医学院的视频,市场告诉他,人们想要的是他的生产力建议。于是,对他来说,倾向于那个更有价值的方向——考虑到他们在一颗葡萄上做手术——是显而易见的选择,而回报是超过10名医生加起来的收入。</p><h3 id="_2-成为一名价值创造者" tabindex="-1">2) 成为一名价值创造者 <a class="header-anchor" href="#_2-成为一名价值创造者" aria-label="Permalink to &quot;2) 成为一名价值创造者&quot;">​</a></h3><p>如果我们观察进化的方向,不妨假设现实的目标是统一意识。</p><p>我们可以通过观察不断增加的完整性模式,来推断出这个方向。</p><p>物质到生物到心理到精神——每一层都超越并包含前一层。</p><p>原子到细胞到分子到有机体。</p><p>字母到句子到段落到章节到书籍。</p><p>材料到基础设施到表面到房屋。</p><p>所有智能生命都在通过创造价值,朝着更高层次的统一迈进。或者说,是在创造财富,以对抗熵所带来的混乱和不确定性。</p><p>现在,如果我们看看心理发展的各个阶段,可以发现一个类似的方向。</p><p>当一个人自我发展时,会从以自我为中心,到以社会为中心,到以世界为中心,再到以宇宙为中心。他们的关切范围不断扩大。他们的欲望也从自私的生存,转变为无私的贡献。</p><p>那么,这整套“创作者事业”到底是为谁准备的?</p><p>在我看来,是那些处于“成就者”到“战略家”阶段及以上的人。大约不到人口的一半。“成就者”似乎是普通自助人群,“专家”似乎是“上学、找工作、退休”那一类人群。</p><p>它是为那些热爱学习、在特定技能或兴趣上已有成果、并想要顺应自己天生渴望帮助他人和进化的欲望而学习的人准备的。</p><p><img src="'+i+'" alt=""></p><p>并不是说所有人都做不到这件事。而是从大多数人的视角来看,这甚至根本不会被识别为一个机会。它说不通。在较低阶段,人们的需求是不同的——关注的是生存和自我。他们不关心这些东西。</p><p>“成就者”阶段是大多数已经接触并理解自我提升与价值实现重要性的人所处的阶段。</p><p><img src="'+o+'" alt=""></p><p>创作者商业模式美妙之处在于,它在很大程度上是与阶段无关的。</p><p>它可以被用作一种强制推动力,把人从常规阶段推向后常规阶段。</p><p>正如我之前在推特上说过的:“<em>自我发展是通向创业的入门毒品,因为你会意识到,提升他人是提升自己的下一个层次。</em>”</p><p>在更高阶段,为人类做出贡献会成为首要任务和渴望。既然金钱和财富是反熵的,创造价值(产品)和传播知识(内容)就是满足这种渴望的可行方式。为成为并实现真正的自己而获得报酬。</p><p>最后一点:</p><p>人类在能力的边界处找到意义和乐趣。当信息流动被最大化的时候。当他们感觉自己有能力去迎接更高挑战的时候。</p><p>所以,如果我们把自己视为让现实得以流经的创造性容器,那正是创作者事业的本质。</p><p>我们学习、创造、传授。</p><p>我们解决自己的问题,并出售解决方案,以增加财富的长尾收益,并为意识的统一做出贡献。</p><h3 id="_3-你的公立学校与生态系统" tabindex="-1">3) 你的公立学校与生态系统 <a class="header-anchor" href="#_3-你的公立学校与生态系统" aria-label="Permalink to &quot;3) 你的公立学校与生态系统&quot;">​</a></h3><p>让我们把这一切落到实处。</p><p>我们刚才有点扯远了。</p><p>想要打造一个以教育和自我提升为核心、而非像典型网红那样专注于表情包和无脑娱乐的价值创造者事业,你需要三件事。</p><ol><li><strong>品牌</strong> —— 你自身的延伸。你的思想在网络上呈现的方式。让人们能够找到并关注你视角的方式。</li><li><strong>内容</strong> —— 你围绕自己的技能和兴趣,分发教育、知识和智慧以帮助他人的方式。</li><li><strong>产品</strong> —— 一个帮助人们解决问题、实现目标的系统。</li></ol><p>你的品牌,是你邀请人们进入的那个世界。</p><p>是你在帮助他们采纳的视角。</p><p>是你在帮助他们达到的目标或发展水平。</p><p>虽然这体现在你的个人简介、头像和品牌设计中,但我认为内容才起着最大的作用。</p><p>你的品牌,是在你受众心中,经过3到6个月不断积累而成的想法总和。</p><p>现在,我们希望我们的内容能与现实相一致。</p><p>是相互关联的、有机的。</p><p>而不是那种快速、碎片化的销售漏斗,让你感觉自己像个油腔滑调的营销人员,不惜一切代价只为最大化利润。</p><p>并不是说你不能那样做,或者说在你必须经历成长的较低发展水平时不应该那样做(请不要把“较低”与“坏”混为一谈,当它们是必要的时候),但我假设,你之所以从事这份工作,是因为你想要比目前所认知的更深层的东西。</p><p>换句话说,我们正在构建一个内容生态系统。</p><p>我们在为人们开辟属于自己的小小互联网角落,供他们加入、学习,并从这里进化到下一个阶段。</p><p>我是这样做的:</p><ul><li>每天写社交媒体帖子</li><li>将这些帖子发布到所有平台</li><li>挑选表现最好的想法</li><li>把它们扩展成更深入的新闻通讯或推文串</li><li>把新闻通讯发布在我的个人博客/网站上</li><li>把这些新闻通讯转化为视频和播客脚本</li><li>在其中穿插链接我的产品,方便人们发现</li><li>将我的视频嵌入对应的博客文章中</li><li>在所有社交平台上“推广”那篇博客文章</li></ul><p>由于我只专注于写帖子和新闻通讯(以及每周坐下来对着镜头读一次),这每天花不了1到2个小时。这是一个非常高效的系统。当然,构建和实验一款产品需要更多时间,但一旦数字产品建成,你就不需要太多维护工作了。</p><p>这创造了一个循环的、相互关联的“学校系统”,让人们可以根据自己的目标去探索,并获取他们所需要的东西。</p><p>当然,我们这里篇幅有限,如果你想要实现这一切的全部系统,我在<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学(Digital Economics)</a>——一门终身事业大师课——中教授了这些内容。</p><h3 id="_4-销售高价值产品" tabindex="-1">4) 销售高价值产品 <a class="header-anchor" href="#_4-销售高价值产品" aria-label="Permalink to &quot;4) 销售高价值产品&quot;">​</a></h3><p>提醒:这部分内容可能会比较长且复杂,但会为你提供关于销售产品的一个有意义的视角。</p><p>创业的未来,是教育、意义和价值交换的融合。</p><p>你已经能在周围到处看到这一点了。</p><p>个人正在创造从课程到服装到软件,再到有益于人类而非伤害人类的整体性实体产品的一切。</p><p>当我说“销售高价值产品”时,我的意思是这样的:</p><p>销售一款有助于人们达到新发展阶段的产品。新的意识阶段。新的心智层次。帮助人们打破自身的局限,拓展自我意识的边界。</p><p>做到这一点的方式是无穷无尽的,所以我把这留给你的创造力去发挥。</p><p>但如果你想听听我的看法,教育类产品是最好的起点。</p><ul><li>它们几乎是零成本创建和分发的。你可以从像电子书这样简单的东西开始,随着时间推移,让它演变成更复杂的课程或训练营。</li><li>实体产品可能有帮助,但实体产品并不是改变的必需品。教育和认知才是任何行为改变的绝对必要前提。</li><li>它们盈利能力强且可扩展。高利润率、无运营成本、也没有物流或供应链问题。这创造了一种高杠杆的生活方式。你可以按自己想要的方式生活。</li><li>你先建立现金流,并验证未来的产品想法。你可以不依靠投资人打造你的下一个创业项目,而且已经拥有一群潜在买家的受众。</li></ul><p>在我看来,从教育入手,似乎是对世界产生影响的最直接、最充实、也最真正有影响力的方式。</p><p>更不用说,经济偏爱盈利能力,而在这个充满不确定性的世界里,对教育的市场需求也很高。</p><p>“但这个领域不会变得饱和吗?”</p><p>并不会。</p><p>我们之前谈到过熵作为一种普遍法则。</p><p>随着选择和不确定性的增加,创造财富的潜力也随之增加。资源在增加。效率在提升。进化被迫发生。</p><p>当然,未来10年这个领域可能会发生剧烈变化,但这正是我们要建立受众、发展自己、并把自己置于既能发现又能利用这种变化的正确位置的原因。</p><p>但就目前而言,像Zoom这样的实时学习工具已经被更广泛地接受。越来越多的人在学校之外投资于进一步的教育。电子学习正在以加速的速度被采纳。教育领域整体市场和机会已经呈指数级增长。</p><p>说到饱和这个话题,人们为什么会从你这里买东西,而不是从别人那里?市场上的信息类产品还不够多吗?</p><p>如果我们回顾一下心理发展的各个阶段,我认为,在每个人都达到统合阶段或更高之前,教育永远都是不够的,而这在<em>很长一段时间内</em>不太可能发生。</p><p>现在,眼下最有利可图的产品,是那些帮助人们达到或超越“成就者”和“多元论者”阶段的产品。</p><p>在我们所关注的语境中,“成就者”和“多元论者”阶段最容易在那些深陷于自我提升、职业发展与商业、培养人际关系、情绪管理与调节,以及初级灵性阶段的人身上看到。</p><p>换句话说,就是我们之前讨论过的那些永恒市场。健康、财富、关系,以及幸福。</p><p>这就是为什么社交媒体和YouTube上充斥着这类视频。因为那些正是(对自我发展感兴趣的)大多数人群所处的阶段。</p><p>问题是,这些视频和内容<em>并不专注于帮助人们迈向下一个阶段</em>。它们专注的是在该阶段内的横向增长,而不是纵向增长。</p><p>你可以瞄准更高的阶段，没问题，但要明白，这些阶段会更难吸引到人。处于更高阶段的人所占比例更小（除非行为改变类的教育/意识提升有所增加，情况才会改变）。</p><p>如何打造一个能盈利的产品？</p><ul><li><strong>选择一种媒介</strong>——电子书、付费通讯、课程、训练营、教练辅导等等。</li><li><strong>选择一个领域</strong>——你的产品可以融合多个主题，但主要焦点应该放在健康、财富、关系或幸福上。</li><li><strong>把产品卖给过去的自己</strong>——回想一下你人生中解决过的某个问题。这可以简单到一份预算表格、教授一项技能（财富领域）、健身计划（健康领域），甚至是一个效率系统。</li><li><strong>卖已经在卖的东西，但做得更好</strong>——研究一下市场上目前正在畅销的东西，然后把它变成自己的版本。</li><li><strong>尝试一个独特的体系</strong>——测试大量他人的方法（比如训练计划或效率规划工具）。</li><li><strong>规划并搭建你的产品</strong>——制定一个大纲，解决一个重大问题，帮助顾客在生活中达到他们想要的结果。</li><li><strong>用自己的视角过滤一切</strong>——去掉不符合你目标的信息，加入能帮助人们接受你视角的信息。</li></ul><p><a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">心理变现（Mental Monetization）</a>可以在这方面帮到你更多。</p><p>接下来，人们学习效果最好的对象，是那些<em>处于</em>他们所在阶段的人，或者高出一两个阶段、能够俯视并绘制出地图的人。你的地图，就是你的产品。</p><p>别人可能卖着类似的产品，讲着同样的内容，但有些人永远不会找到他们。你关注一个人，并不是因为他教的内容，而是因为他的个性和目标。</p><p>我可以在网上搜索一个网页设计课程，但如果我一开始压根就没有对网页设计的兴趣呢？如果是我关注的那个人把这个领域介绍给我的呢？在那种情况下，我唯一会付费购买的对象，就是那个特定的人。</p><p>当你通过你的产品，让人们接触到他们自我发展的下一个层次，从而创造出一个市场时，市场有多饱和根本无关紧要。</p><p>这封信就在这里结束吧。</p><p>内容有点长了，我们可能需要在另一封专门针对这些主题的信里，进一步展开其中一些话题。</p><p>在此期间，如果你想读点别的，我觉得这篇关于<a href="/letters/the-value-equation-how-to-become-a-top-1-individual-fast">价值创造</a>的信，能帮你理解是什么让一个产品真正能赚钱。</p><p>下周再聊，</p><p>——丹（Dan）</p><hr><p><a href="/en/letters/the-best-one-person-business-for-smart-people-2025">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',188))])}const S=s(_,[["render",b]]);export{T as __pageData,S as default};
